	switch v := meta.TypedPayload.(type) {
	case PresencePeerPresenceAlivePayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceAlive
		p.pendingPresenceAlivePayload = v
	case PresencePeerPresenceBeatPayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceBeat
		p.pendingPresenceBeatPayload = v
	case PresencePeerPresenceExpirePayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceExpire
		p.pendingPresenceExpirePayload = v
	case PresencePeerPresenceJoinPayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceJoin
		p.pendingPresenceJoinPayload = v
	case PresencePeerPresenceLeftPayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceLeft
		p.pendingPresenceLeftPayload = v
	case PresencePeerPresenceSeenPayload:
		p.pendingPayloadTag = PresencePeerPayloadTagPresenceSeen
		p.pendingPresenceSeenPayload = v
	}

	p.pendingEventData = meta.Data
	p.pendingEventInvokeid = meta.InvokeID
